sketch.css:
.ab{container-type:inline-size;box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.ab *{box-sizing:border-box}
.head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap}
.title{font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.sums{display:flex;align-items:baseline;gap:10px;font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.sums b{color:var(--text);font-weight:700}
.past b.pp{color:var(--negative);font-weight:700;margin-left:4px}
.cols,.row{display:grid;grid-template-columns:62px minmax(40px,1fr) 78px 52px 46px;align-items:center;gap:8px}
.cols{padding:2px 6px;color:var(--muted);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.03em;border-bottom:1px solid var(--border);white-space:nowrap}
.c-amt,.c-cnt,.c-pct{text-align:right}
.rows{flex:1;min-height:0;display:flex;flex-direction:column;gap:2px}
.row{flex:1 1 0;min-height:22px;max-height:44px;padding:2px 6px;border-radius:6px;cursor:pointer;border:1px solid transparent}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);border-color:var(--accent)}
.bk{font-weight:600;white-space:nowrap}
.track{position:relative;height:12px;border-radius:5px;background:var(--background)}
.fill{position:absolute;left:0;top:0;bottom:0;border-radius:5px;background:var(--b0)}
.b1 .fill{background:var(--b1)}
.b2 .fill{background:var(--b2)}
.b3 .fill,.b4 .fill{background:var(--b3)}
.amt{text-align:right;font-weight:600;font-variant-numeric:tabular-nums;white-space:nowrap}
.cnt,.pct{text-align:right;font-variant-numeric:tabular-nums;color:var(--muted);white-space:nowrap}
.pct{color:var(--text);font-weight:600}
.b4 .bk,.b4 .amt{color:var(--negative)}
.empty{color:var(--muted);font-size:12px;padding:20px 0;text-align:center}
@container (max-width:420px){
  .cols,.row{grid-template-columns:54px minmax(40px,1fr) 70px 42px}
  .c-cnt,.cnt{display:none}
}

