function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const unit = props.unit == null ? '$' : String(props.unit);
  const compact = v => {
    const a = Math.abs(v), sg = v < 0 ? '-' : '';
    const f = (x, s) => {
      let t = x >= 100 ? x.toFixed(0) : x >= 10 ? x.toFixed(1) : x.toFixed(2);
      if (t.indexOf('.') >= 0) t = t.replace(/0+$/, '').replace(/\.$/, '');
      return sg + t + s;
    };
    if (a >= 1e9) return f(a / 1e9, 'B');
    if (a >= 1e6) return f(a / 1e6, 'M');
    if (a >= 1e3) return f(a / 1e3, 'K');
    return sg + String(Math.round(a));
  };
  const money = v => unit + compact(v);
  const rows = (props.buckets || []).map(r => ({
    bucket: String(r.bucket == null ? '' : r.bucket),
    amount: Math.max(0, +r.amount || 0), count: Math.max(0, Math.round(+r.count || 0))
  })).filter(r => r.bucket !== '');
  const total = rows.reduce((a, r) => a + r.amount, 0);
  const past = rows.slice(1).reduce((a, r) => a + r.amount, 0);
  const pastPct = total > 0 ? Math.round(past / total * 100) : 0;

  root.querySelector('.title').textContent = props.title || 'Aging';
  root.querySelector('.total').innerHTML = 'Total <b>' + esc(money(total)) + '</b>';
  root.querySelector('.past').innerHTML = 'Past due <b>' + esc(money(past)) + '</b><b class="pp">' + pastPct + '%</b>';

  const box = root.querySelector('.rows');
  if (!rows.length) { box.innerHTML = '<div class="empty">No balances</div>'; return; }
  const max = Math.max(1, ...rows.map(r => r.amount));
  box.innerHTML = rows.map((r, i) => {
    const pct = total > 0 ? r.amount / total * 100 : 0;
    return '<div class="row b' + Math.min(i, 4) + (r.bucket === props.selected ? ' selected' : '') + '" data-bucket="' + esc(r.bucket) + '" title="' +
      esc(r.bucket + ': ' + money(r.amount) + ', ' + r.count + ' item' + (r.count === 1 ? '' : 's') + ', ' + pct.toFixed(1) + '% of total') + '">' +
      '<span class="bk">' + esc(r.bucket) + '</span>' +
      '<div class="track"><div class="fill" style="width:' + (r.amount / max * 100).toFixed(2) + '%"></div></div>' +
      '<span class="amt">' + esc(money(r.amount)) + '</span>' +
      '<span class="cnt">' + r.count + '</span>' +
      '<span class="pct">' + Math.round(pct) + '%</span></div>';
  }).join('');
  box.querySelectorAll('.row').forEach(el => el.onclick = () => fire('bucketSelected', { bucket: el.dataset.bucket, selected: el.dataset.bucket }));
}
